// Match L# tags from an IMAP-delivered reply against recent sent-mapping
// files, and load preferences.json. Outputs the same shape the existing
// "Apply feedback to preferences" node expects: { feedbacks, prior_prefs }.
//
// Reusable email-app pattern:
//   * IMAP trigger fires once per matching message
//   * Skip non-replies (subject doesn't start with "Re:")
//   * Parse the message body for command tokens (here: L# + sentiment)
//   * Resolve each token against on-disk state (here: sent-YYYY-MM-DD.json)
//   * Hand off to a downstream "Apply" code node
//
// Other email-driven projects can copy this node verbatim and just swap:
//   - the regex used to extract command tokens
//   - the on-disk state directory + filename pattern
//   - the lookup function

const fs = require('fs');
const path = require('path');

const SHARED_DIR = '/data/shared/rentals';
const SENT_DIR   = path.join(SHARED_DIR, 'sent');
const PREFS_PATH = path.join(SHARED_DIR, 'preferences.json');

// Acceptable thumbs/keywords (case-insensitive)
const POS_PAT = /(?:👍|\blike\b|\blove\b|\byes\b|\bgood\b|\b\+\b)/i;
const NEG_PAT = /(?:👎|\bdislike\b|\bno\b|\bbad\b|\bhate\b|\B-\B)/i;
const TAG_PAT = /\bL(\d+)\b([^\n]*)/gi;

// Load all sent-mappings, newest-first, so a delayed reply still resolves.
// Returns: array of {date, mapping}
function loadSentMappings() {
  let files;
  try {
    files = fs.readdirSync(SENT_DIR)
      .filter(f => /^sent-\d{4}-\d{2}-\d{2}\.json$/.test(f))
      .sort()
      .reverse();
  } catch (e) {
    return [];
  }
  const out = [];
  for (const f of files.slice(0, 14)) {  // last 14 days is enough
    try {
      const raw = fs.readFileSync(path.join(SENT_DIR, f), 'utf8');
      const obj = JSON.parse(raw);
      // Support both shapes: {mapping: {L1: ...}} OR {L1: ...}
      const mapping = obj.mapping || obj;
      out.push({ date: f.replace(/^sent-|\.json$/g, ''), mapping });
    } catch (e) { /* skip malformed */ }
  }
  return out;
}

function loadPrefs() {
  try {
    return JSON.parse(fs.readFileSync(PREFS_PATH, 'utf8'));
  } catch (e) {
    return null;
  }
}

// Strip the quoted reply trailer ("On <date> <name> wrote:" and below)
function stripQuotedReply(body) {
  return (body || '').split(/\n\s*On .+wrote:/)[0].slice(0, 4000);
}

const messages = $input.all();
const prefs = loadPrefs();
if (!prefs) {
  return [{ json: { __error: 'preferences.json missing or unparseable; aborting' } }];
}

const sentMappings = loadSentMappings();
const feedbacks = [];

for (const m of messages) {
  const msg = m.json;
  const subject = String(msg.subject || '');
  // Drop the watcher's OWN outgoing self-loops (Gmail mirrors self-sends to inbox)
  if (!/^\s*Re:/i.test(subject)) continue;

  // IMAP simple format gives us text directly — no base64 decode needed
  const body = stripQuotedReply(msg.textPlain || msg.text || msg.textHtml || msg.textAsHtml || '');

  let mt;
  TAG_PAT.lastIndex = 0;
  while ((mt = TAG_PAT.exec(body)) !== null) {
    const tag = `L${mt[1]}`;
    const trail = (mt[2] || '').trim();
    const isPos = POS_PAT.test(trail);
    const isNeg = NEG_PAT.test(trail);
    if (!isPos && !isNeg) continue;

    // Resolve tag against the most recent mapping that contains it
    let listing = null;
    let resolvedFromDate = null;
    for (const sm of sentMappings) {
      if (sm.mapping && sm.mapping[tag]) {
        listing = sm.mapping[tag];
        resolvedFromDate = sm.date;
        break;
      }
    }
    if (!listing) continue;  // tag not found in any recent mapping

    feedbacks.push({
      tag,
      sentiment: isPos ? 'like' : 'dislike',
      comment: trail.replace(POS_PAT, '').replace(NEG_PAT, '').trim(),
      listing,
      message_id: msg.messageId || null,
      received_at: msg.date ? new Date(msg.date).toISOString() : null,
      resolved_from: resolvedFromDate,
    });
  }
}

return [{ json: { feedbacks, prior_prefs: prefs } }];

// Update preferences.json with the new feedback.
// Strategy: extract neighborhood + distinctive keywords from each rated listing,
// then append to prefs.likes / prefs.dislikes (deduped).
//
// Also write a feedback-log.jsonl entry for human inspection.

const it = $input.first();
if (it.json.__error) return [{ json: { error: it.json.__error } }];

const { feedbacks, prior_prefs } = it.json;
if (!feedbacks || feedbacks.length === 0) {
  // No feedback to apply — return current prefs unchanged so we still write a no-op
  const noop = JSON.stringify(prior_prefs, null, 2);
  return [{
    json: { applied: 0, message: 'no feedback found' },
    binary: {
      prefs: {
        data: Buffer.from(noop, 'utf8').toString('base64'),
        mimeType: 'application/json',
        fileName: 'preferences.json'
      },
      log: {
        data: Buffer.from('', 'utf8').toString('base64'),
        mimeType: 'application/jsonl',
        fileName: 'feedback-log.jsonl'
      }
    }
  }];
}

const prefs = JSON.parse(JSON.stringify(prior_prefs));
prefs.likes = prefs.likes || [];
prefs.dislikes = prefs.dislikes || [];

function extractKeywords(listing) {
  const out = new Set();
  const haystack = `${listing.title || ''} ${listing.location || ''}`.toLowerCase();
  const hoods = ['rosemont', 'mile end', 'mile-end', 'plateau', 'villeray', 'outremont', 'petite-patrie', 'petite italie', 'little italy', 'jean-talon', 'beaubien', 'maisonneuve', 'masson', 'laurier'];
  for (const h of hoods) if (haystack.includes(h)) out.add(h);
  const desc = ['sous-sol', 'rdc', 'rdj', 'duplex', 'triplex', 'maison', 'townhouse', 'rénové', 'renovated', 'garage', 'stationnement', 'cour', 'jardin', 'terrasse', 'basement'];
  for (const d of desc) if (haystack.includes(d)) out.add(d);
  return [...out];
}

const applied = [];
for (const fb of feedbacks) {
  const kws = extractKeywords(fb.listing);
  if (fb.comment && fb.comment.length > 2 && fb.comment.length < 80) {
    kws.push(fb.comment.toLowerCase());
  }
  const target = fb.sentiment === 'like' ? prefs.likes : prefs.dislikes;
  for (const kw of kws) {
    if (!target.includes(kw)) target.push(kw);
  }
  applied.push({ tag: fb.tag, sentiment: fb.sentiment, keywords_added: kws });
}

prefs.updated_at = new Date().toISOString();
prefs.version = (prefs.version || 1) + 1;

const prefsJson = JSON.stringify(prefs, null, 2);
const logLines = feedbacks.map(fb => JSON.stringify({
  ts: new Date().toISOString(),
  tag: fb.tag,
  sentiment: fb.sentiment,
  comment: fb.comment,
  listing_url: fb.listing.url,
  listing_title: fb.listing.title,
  message_id: fb.message_id,
  resolved_from: fb.resolved_from,
})).join('\n') + '\n';

return [{
  json: { applied: feedbacks.length, summary: applied, new_likes_count: prefs.likes.length, new_dislikes_count: prefs.dislikes.length },
  binary: {
    prefs: {
      data: Buffer.from(prefsJson, 'utf8').toString('base64'),
      mimeType: 'application/json',
      fileName: 'preferences.json'
    },
    log: {
      data: Buffer.from(logLines, 'utf8').toString('base64'),
      mimeType: 'application/jsonl',
      fileName: 'feedback-log.jsonl'
    }
  }
}];
